function filteredReviewItems(){
  const items=tx.filter(t=>{
    const confidence=confidenceOf(t);
    return (!reviewState.statementId||t.statement_id===reviewState.statementId)&&(!reviewState.q||`${t.description} ${t.merchant||''}`.toLowerCase().includes(reviewState.q))&&(!reviewState.allocation||(reviewState.allocation==='Needs review'?(t.allocation==='Needs review'||t.ocr_amount_match===0):t.allocation===reviewState.allocation))&&(!reviewState.kind||t.kind===reviewState.kind)&&(!reviewState.person||t.person===reviewState.person)&&(!reviewState.confidence||(reviewState.confidence==='low'?(t.ocr_amount_match===0||(confidence!==null&&confidence<80)):(confidence!==null&&confidence>=80&&t.ocr_amount_match!==0)));
  });
  if(reviewState.sort==='confidence')items.sort((a,b)=>(confidenceOf(a)??Infinity)-(confidenceOf(b)??Infinity)||((a.ocr_amount_match===0?-1:0)-(b.ocr_amount_match===0?-1:0))||b.date.localeCompare(a.date));
  else items.sort((a,b)=>b.date.localeCompare(a.date));
  return items;
}
function updateBulkBar(){const count=reviewState.selected.size;const label=$('#selected-count');if(label)label.textContent=`${count} selected`;const selected=[...reviewState.selected].map(id=>tx.find(t=>t.id===id)).filter(Boolean),hasPayment=selected.some(t=>t.kind==='Card payment'),hasExpense=selected.some(t=>t.kind!=='Card payment');$$('[data-bulk-allocation]').forEach(button=>button.disabled=count===0||(button.dataset.bulkAllocation==='Card payment'?!hasPayment:!hasExpense));$$('[data-undo-review]').forEach(button=>button.disabled=!reviewUndo)}
function renderBulkPreview(){const box=$('#bulk-confirmation');if(!box)return;if(!bulkPreview){box.hidden=true;box.innerHTML='';return}const skipped=bulkPreview.skipped;box.hidden=false;box.innerHTML=`<span>Apply <b>${esc(bulkPreview.allocation)}</b> to <b>${bulkPreview.ids.length}</b> selected line items?${skipped?` ${skipped} card payment line${skipped===1?' stays':'s stay'} unchanged.`:''}</span><div><button class="button small" data-cancel-bulk>Cancel</button><button class="button small primary" data-confirm-bulk>Apply to ${bulkPreview.ids.length}</button></div>`}
function visibleReviewItems(){const items=filteredReviewItems();return items.filter(t=>t.kind==='Purchase'||reviewState.otherOpen)}
function reviewTableMarkup(bodyId,items){return `<table class="review-table"><thead><tr><th class="check-col"></th><th>Merchant / statement line</th><th>Date</th><th>Cardholder</th><th class="right">INR amount</th><th>Allocation · amount owed</th><th></th></tr></thead><tbody id="${bodyId}">${items.length?items.map(reviewRow).join(''):`<tr><td colspan="7"><div class="empty"><strong>No matching transactions</strong>Change the filters or search to see more.</div></td></tr>`}</tbody></table>`}
