document.addEventListener('change',e=>{if(e.target.matches('[data-discovery-result]')){const card=e.target.closest('[data-discovery-card]'),item=discoveries.find(d=>d.id===card?.dataset.discoveryId),result=item?.results?.[Number(e.target.value)];if(result){const brand=$('[data-discovery-brand]',card),legal=$('[data-discovery-legal]',card);if(brand&&!brand.dataset.edited)brand.value=result.suggested_brand_name||item.raw_alias;if(legal&&!legal.dataset.edited)legal.value=result.suggested_legal_name||''}return}if(e.target.matches('[data-home-month]')){const m=e.target.dataset.homeMonth;homeFilter.months=e.target.checked?[...new Set([...homeFilter.months,m])]:homeFilter.months.filter(x=>x!==m);homeFilter.bank='';homeFilter.card='';homeFilter.monthMenuOpen=true;render();return}if(e.target.id==='home-bank'){homeFilter.bank=e.target.value;homeFilter.card='';render();return}if(e.target.id==='home-card'){homeFilter.card=e.target.value;render();return}if(e.target.id==='filter-sort'){reviewState.sort=e.target.value;renderReviewRows()}if(e.target.id==='filter-status'||e.target.id==='filter-kind'||e.target.id==='filter-person'||e.target.id==='filter-confidence'||e.target.id==='filter-statement'){reviewState.statementId=$('#filter-statement').value;reviewState.allocation=$('#filter-status').value;reviewState.kind=$('#filter-kind').value;reviewState.person=$('#filter-person').value;reviewState.confidence=$('#filter-confidence').value;reviewState.otherOpen=Boolean(reviewState.kind&&reviewState.kind!=='Purchase');reviewState.selected.clear();bulkPreview=null;activeReviewId=null;renderReviewRows()}if(e.target.id==='select-visible'){visibleReviewItems().forEach(t=>e.target.checked?reviewState.selected.add(t.id):reviewState.selected.delete(t.id));bulkPreview=null;renderReviewRows()}if(e.target.matches('[data-select-id]')){e.target.checked?reviewState.selected.add(e.target.dataset.selectId):reviewState.selected.delete(e.target.dataset.selectId);bulkPreview=null;const row=e.target.closest('[data-review-row]');activeReviewId=row?.dataset.reviewRow||activeReviewId;updateBulkBar();renderBulkPreview();const items=visibleReviewItems(),select=$('#select-visible');if(select){select.checked=items.length>0&&items.every(t=>reviewState.selected.has(t.id));select.indeterminate=items.some(t=>reviewState.selected.has(t.id))&&!select.checked}}if(e.target.id==='allocation')$('#share-wrap').classList.toggle('hidden',e.target.value!=='Custom')});
document.addEventListener('keydown',e=>{if(currentView!=='transactions'||e.metaKey||e.ctrlKey||e.altKey||e.target.matches('input,select,textarea,[contenteditable="true"]')||$('#transaction-dialog').open||$('#statement-dialog').open||$('#merchant-dialog').open||$('#spotlight-dialog').open)return;const items=filteredReviewItems();if(!items.length)return;let index=items.findIndex(t=>t.id===activeReviewId);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();index=index<0?0:Math.min(items.length-1,Math.max(0,index+(e.key==='ArrowDown'?1:-1)));activeReviewId=items[index].id;if(items[index].kind!=='Purchase')reviewState.otherOpen=true;renderReviewRows();$(`[data-review-row="${activeReviewId}"]`)?.focus({preventScroll:true});return}if(e.key==='Escape'){reviewState.selected.clear();bulkPreview=null;renderReviewRows();return}const allocation={s:'Shared',w:'Wife personal',m:'Your personal'}[e.key.toLowerCase()];if(allocation&&activeReviewId){e.preventDefault();applyReviewAllocation([activeReviewId],allocation)}else if(e.key.toLowerCase()==='p'&&activeReviewId&&tx.find(t=>t.id===activeReviewId)?.kind==='Card payment'){e.preventDefault();applyReviewAllocation([activeReviewId],'Card payment')}});
document.addEventListener('submit',async e=>{if(e.target.matches('[data-passkey-rename]')){e.preventDefault();const form=e.target,id=form.dataset.passkeyRename,button=form.querySelector('button');button.disabled=true;try{await api('/api/auth/passkeys/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify({nickname:new FormData(form).get('nickname')})});await loadPasskeys();if(currentView==='settings')render();toast('Passkey name updated')}catch(err){toast(err.message);button.disabled=false}return}if(e.target.id==='add-user-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/admin/users',{method:'POST',body:JSON.stringify(d)});$('#add-user-dialog').close();await load();setView('settings');toast('Household account created')}catch(err){toast(err.message)}return}if(e.target.id==='reset-user-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries()),id=d.user_id;try{await api('/api/admin/users/'+id+'/password',{method:'POST',body:JSON.stringify({password:d.password})});$('#reset-user-dialog').close();toast('Password reset; previous sessions ended')}catch(err){toast(err.message)}return}if(e.target.id==='password-form'){e.preventDefault();const d=Object.fromEntries(new FormData(e.target).entries());try{await api('/api/auth/password',{method:'POST',body:JSON.stringify(d)});location.replace('/')}catch(err){toast(err.message)}}});
$('#transaction-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f).entries());d.share_percent=Number(d.share_percent||0);d.amount_inr=Number(d.amount_inr||0);if(d.original_amount==='')d.original_amount=null;try{if(d.id)await api('/api/transactions/'+d.id,{method:'PUT',body:JSON.stringify(d)});else await api('/api/transactions',{method:'POST',body:JSON.stringify(d)});$('#transaction-dialog').close();await load();toast('Transaction saved')}catch(err){toast(err.message)}});
$('#statement-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,d=Object.fromEntries(new FormData(f).entries()),file=d.file;if(!file)return;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('Could not read this PDF'));reader.readAsDataURL(file)});const result=await api('/api/statements',{method:'POST',body:JSON.stringify({bank:d.bank,card_name:d.card_name,period:d.period,filename:file.name,data})});$('#statement-dialog').close();await load();pollDiscoveryQueue();setView('statements');toast(result.extraction_status==='ready'?`HSBC: ${result.transaction_count} lines added as Needs review`:result.extraction_status==='error'?`PDF saved; extraction failed: ${result.message}`:result.extraction_status==='empty'?'PDF saved; no lines recognized for review':'PDF saved')}catch(err){toast(err.message)}});
$('#merchant-form').addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget).entries());d.aliases=d.aliases.split(',').map(x=>x.trim()).filter(Boolean);try{if(d.id)await api('/api/merchants/'+d.id,{method:'PUT',body:JSON.stringify(d)});else await api('/api/merchants',{method:'POST',body:JSON.stringify(d)});$('#merchant-dialog').close();await load();setView('merchants');toast(d.id?'Merchant updated':'Merchant added')}catch(err){toast(err.message)}});
$('#transaction-form [name="description"]').addEventListener('input',e=>{const raw=e.target.value.toLowerCase();const match=merchants.find(m=>m.aliases.some(a=>raw.includes(a.toLowerCase()))||raw.includes(m.display_name.toLowerCase()));if(match)$('#merchant-select').value=match.id});
$('#search-shortcut').addEventListener('click',openSpotlight);$('#sidebar-toggle').addEventListener('click',()=>sidebarState(!sidebarCollapsed));sidebarState(sidebarCollapsed);$('#spotlight-dialog').addEventListener('click',e=>{if(e.target===$('#spotlight-dialog'))$('#spotlight-dialog').close()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSpotlight();return}if(!$('#spotlight-dialog').open)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();spotlightIndex=Math.max(0,Math.min(spotlightResults.length-1,spotlightIndex+(e.key==='ArrowDown'?1:-1)));renderSpotlight();const active=$('[data-spotlight-index="'+spotlightIndex+'"]');active?.scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&spotlightResults.length){e.preventDefault();const result=spotlightResults[spotlightIndex];if(result.type==='recent'){$('#spotlight-query').value=result.label;spotlightIndex=0;renderSpotlight()}else openSpotlightResult(result,$('#spotlight-query').value)}});
initialize().catch(e=>toast(e.message));
